import React from 'react';
import { Navbar, Container, Button, Dropdown } from 'react-bootstrap';

function Header({ username, onLogout }) {
    const defaultAvatar = 'https://unsplash.com/photos/a-cartoon-character-wearing-a-purple-shirt-and-a-red-headband-xRMK0ea-Of4'
    return (
        <Navbar bg="dark" variant="dark" className="py-3">
        <Container fluid>
            {/* App Name / Logo */}
            <Navbar.Brand href="/chat" className="me-auto">
            Chat App
            </Navbar.Brand>

            {/* User Dropdown */}
            <div className="d-flex align-items-center">
            <Dropdown align="end">
                <Dropdown.Toggle variant="dark" id="user-dropdown" className="rounded p-2">
                <img
                    src={defaultAvatar}
                    alt="User Avatar"
                    className="rounded-circle me-2"
                    width="32"
                    height="32"
                />
                <span className="fw-bold">{username}</span>
                </Dropdown.Toggle>

                <Dropdown.Menu>
                <Dropdown.Item onClick={onLogout} className="text-danger">
                    Logout
                </Dropdown.Item>
                </Dropdown.Menu>
            </Dropdown>
            </div>
        </Container>
        </Navbar>
    );
}

export default Header;
